/**
 * Case M2 — a deliberately wrong controlled transcript. It omits a declared attribute,
 * declares the wrong unit and fabricates an object. The oracle must classify each fault.
 */
const CASE_MODELLING_NEGATIVE: ModellingEvalCase = {
  caseId: 'modelling-faults-detected',
  family: 'modelling',
  description: 'controlled transcript with an error, an omission and a fabrication',
  sourceText:
    'A device has a serial number, a name, a kind (charger or inverter) and a rated power in kW.',
  allowedKinds: ['object', 'attribute', 'relation'],
  terminology: EMPTY_TERMINOLOGY_FALLBACK,
  controlledModelOutput: {
    objects: [definition('device', 'Device'), definition('phantom', 'Phantom')],
    attributes: [
      definition('rated_power', 'Rated power', { objectLogicalId: 'device', valueType: 'quantity', unitCode: 'W' }),
      definition('device_name', 'Name', { objectLogicalId: 'device', valueType: 'string' }),
      definition('device_serial', 'Serial', { objectLogicalId: 'device', valueType: 'string' }),
    ],
    relations: [],
  },
  reference: [
    { key: 'object:device', fields: {} },
    { key: 'attribute:rated_power', fields: { object: 'device', valueType: 'quantity', unit: 'kW', enum: '' } },
    { key: 'attribute:device_name', fields: { object: 'device', valueType: 'string', unit: '', enum: '' } },
    { key: 'attribute:device_kind', fields: { object: 'device', valueType: 'enum', unit: '', enum: 'charger,inverter' } },
  ],
  expected: {
    matched: ['attribute:device_name', 'object:device'],
    missing: ['attribute:device_kind'],
    errors: [{ key: 'attribute:rated_power', field: 'unit', expected: 'kW', observed: 'W' }],
    unexpected: ['attribute:device_serial', 'object:phantom'],
    disambiguation: [],
    requiredCorrections: [
      'correct attribute:rated_power.unit: expected kW, observed W',
      'provide attribute:device_kind',
      'review attribute:device_serial: not in the reference',
      'review object:phantom: not in the reference',
    ],
  },
}

