export const MODELLING_PARAMETER_EVAL_SET: readonly ModellingParameterCase[] = [
  CASE_MODELLING_CATALOG,
  CASE_MODELLING_NEGATIVE,
  CASE_MODELLING_DISAMBIGUATION,
  CASE_PARAMETER_CLEAN,
  CASE_PARAMETER_PRECISION,
  CASE_PARAMETER_UNIT_CONFLICT,
]

export function casesOfFamily(
  set: readonly ModellingParameterCase[],
  family: EvalFamily,
): readonly ModellingParameterCase[] {
  return set.filter((entry) => entry.family === family)
}

/** The fixed input + reference projection the readiness report pins by digest. */
export function evalSetProjection(set: readonly ModellingParameterCase[]): readonly unknown[] {
  return set
    .map((entry) =>
      entry.family === 'modelling'
        ? {
            caseId: entry.caseId,
            family: entry.family,
            sourceText: entry.sourceText,
            allowedKinds: [...entry.allowedKinds].sort(),
            terminology: entry.terminology,
            reference: entry.reference,
          }
        : {
            caseId: entry.caseId,
            family: entry.family,
            sourceText: entry.sourceText,
            schema: entry.schema,
            reference: entry.reference,
          },
    )
    .sort((left, right) => (left.caseId < right.caseId ? -1 : 1))
}
